"""Generate the decoration actor classes and editor numbers from
tools/decor_types.py: src/zscript/gameplay/presentation/Decor.zs and
src/resources/mapinfo/decor.txt. Run: python tools/gen_decor.py
"""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from tools.decor_types import DECOR  # noqa: E402


def class_name(key: str) -> str:
    return "DSDeco" + "".join(part.capitalize() for part in key.split("_"))


def main() -> None:
    lines = [
        "// GENERATED by tools/gen_decor.py from tools/decor_types.py. Do not edit.",
        "// Non-solid ground decoration for the stage maps (tools/art/decor_art*.py):",
        "// placed by the map (room.json \"decor\"), never touched by gameplay.",
        "class DSDecor : Actor",
        "{",
        "    Default",
        "    {",
        "        Radius 1;",
        "        Height 1;",
        "        +NOBLOCKMAP;",
        "        +NOGRAVITY;",
        "        +NOINTERACTION;",
        "        RenderStyle \"Normal\";",
        "    }",
        "}",
        "",
    ]
    for key, (number, sprite, scale) in DECOR.items():
        lines.append(f"class {class_name(key)} : DSDecor {{ Default {{ Scale {scale}; }} States {{ Spawn: {sprite} A -1; Stop; }} }}")
    (ROOT / "src/zscript/gameplay/presentation/Decor.zs").write_text("\n".join(lines) + "\n", encoding="utf-8")
    info = ["// GENERATED by tools/gen_decor.py. Do not edit.", "DoomEdNums", "{"]
    info += [f"    {number} = {class_name(key)}" for key, (number, _, _) in DECOR.items()]
    info.append("}")
    (ROOT / "src/resources/mapinfo/decor.txt").write_text("\n".join(info) + "\n", encoding="utf-8")
    print(f"wrote {len(DECOR)} decor classes")


if __name__ == "__main__":
    main()
